		keyName = "showPathToLocation",
		name = "Show Path",
		description = "Draw a tile path to the closest broken lamp or utility location (bank/wire machine).",
		section = pathSection,
		position = 1
	)
	default boolean showPathToLocation() 
	{
		return true;
