		return 2;
	}

	@Range(min = 0, max = 4)
	@ConfigItem(
		keyName = "borderFeather",
		name = "Border Feather",
		description = "Feathering amount for border-style highlights. 0 to disable.",
		section = highlightStyleSection,
		position = 2
